// Filled in by vite.config.ts's `define` when the editor is built or run.

// PERFBOARD_PROJECTS_URL from the environment, or "" for the public project storage.
declare const __PERFBOARD_PROJECTS_URL__: string;

// True on the dev server (`npm run start`), false in a build: dev-only code sits behind it, so a
// build leaves it out.
declare const __DEV_SERVER__: boolean;
